import type { ClaimedSession } from './session';

/** TASK-56: the localStorage keys. */
export const TOKEN_KEY = 'drift.token';
export const SESSION_KEY = 'drift.session.v1';

/** Read the stored token: 'drift.token' first, else the full session object. */
export function readStoredToken(): string | null {
  try {
    const t = localStorage.getItem(TOKEN_KEY);
    if (t) return t;
    const raw = localStorage.getItem(SESSION_KEY);
    if (!raw) return null;
    const s = JSON.parse(raw) as { token?: unknown };
    return typeof s.token === 'string' ? s.token : null;
  } catch { return null; }
}

export function saveSession(s: ClaimedSession): void {
  localStorage.setItem(SESSION_KEY, JSON.stringify(s));
  localStorage.setItem(TOKEN_KEY, s.token);
}

export function clearStoredSession(): void {
  localStorage.removeItem(SESSION_KEY);
  localStorage.removeItem(TOKEN_KEY);
}

export interface SessionProfile {
  callsign: string; credits: number; playerId: string; homeSystemId: string; lastSystemId: string | null; shipId: string;
}

export type RestoreResult = { ok: true; session: ClaimedSession } | { ok: false };

/**
 * Stored token → GET /api/session → ClaimedSession. 401/404/5xx/network → {ok:false}
 * (the claims screen takes over; no error screen).
 */
export async function restoreSession(token: string, fetchImpl: typeof fetch = fetch): Promise<RestoreResult> {
  try {
    const res = await fetchImpl('/api/session', { headers: { authorization: `Bearer ${token}` } });
    if (!res.ok) return { ok: false };
    const body = (await res.json()) as Partial<SessionProfile>;
    if (typeof body.callsign !== 'string' || typeof body.playerId !== 'string' || typeof body.homeSystemId !== 'string') return { ok: false };
    return { ok: true, session: { token, playerId: body.playerId, callsign: body.callsign, homeSystemId: body.homeSystemId } };
  } catch {
    return { ok: false };
  }
}
```

